import { NextRequest, NextResponse } from "next/server";

const PIPED_INSTANCES = [
  "https://pipedapi.kavin.rocks",
  "https://pipedapi.moomoo.me",
  "https://pipedapi.syncpundit.io"
];

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const title = searchParams.get("title");
    const artist = searchParams.get("artist");

    if (!title || !artist) {
      return NextResponse.json({ error: "Missing parameters" }, { status: 400 });
    }

    const searchQuery = `${artist} ${title} audio`;
    let streamUrl = null;

    for (const apiBase of PIPED_INSTANCES) {
      try {
        // 1. Формируем URL для поиска трека на Piped
        const searchTarget = `${apiBase}/search?q=${encodeURIComponent(searchQuery)}&filter=all`;
        
        // ТРЮК: Оборачиваем запрос в открытый Cloudflare-прокси AllOrigins.
        // Это заставит Node.js (который игнорит твой VPN) идти на разрешенный сервер.
        const searchProxy = `https://api.allorigins.win/raw?url=${encodeURIComponent(searchTarget)}`;
        
        const searchRes = await fetch(searchProxy, { cache: 'no-store' });
        if (!searchRes.ok) continue; 
        
        const searchData = await searchRes.json();
        const video = searchData.items?.find((item: any) => item.type === 'stream');
        
        if (!video) continue;

        const videoId = video.url.split('?v=')[1];
        
        // 2. Формируем запрос на получение потоков и тоже оборачиваем в прокси
        const streamTarget = `${apiBase}/streams/${videoId}`;
        const streamProxy = `https://api.allorigins.win/raw?url=${encodeURIComponent(streamTarget)}`;

        const streamRes = await fetch(streamProxy, { cache: 'no-store' });
        if (!streamRes.ok) continue;
        
        const streamData = await streamRes.json();
        const audioStreams = streamData.audioStreams;
        
        if (audioStreams && audioStreams.length > 0) {
          // Сортируем аудио по качеству (от лучшего к худшему) и берем первое
          const bestAudio = audioStreams.sort((a: any, b: any) => b.bitrate - a.bitrate)[0];
          streamUrl = bestAudio.url;
          break; // Ссылка найдена, выходим из цикла!
        }
      } catch (e) {
        // Если прокси или зеркало отвалилось, молча пробуем следующее
        continue;
      }
    }

    if (!streamUrl) {
      return NextResponse.json(
        { error: "Не удалось найти аудио. Все прокси недоступны." },
        { status: 502 }
      );
    }

    return NextResponse.json(
      { url: streamUrl, title: title },
      { status: 200 }
    );
    
  } catch (error) {
    console.error("Audio API error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}